// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 wei, 1000 ether);
        SelfDestructer helper = new SelfDestructer();
        vm.deal(address(c), amount);
        c.forward(address(helper), "");
        assertTrue(address(c).balance == amount);
    }
}

contract SelfDestructer {
    fallback() external payable {
        selfdestruct(payable(msg.sender));
    }
}
